function StatCard({ label, value, detail, icon: Icon, tint = 'teal' }: { label: string; value: string; detail: string; icon: typeof Target; tint?: 'teal' | 'orange' | 'blue' | 'rose' }) {
  const colors = { teal: 'bg-[#d9ece6] text-[#236f69]', orange: 'bg-[#f9e6cf] text-[#a65d21]', blue: 'bg-[#dce8f1] text-[#456e91]', rose: 'bg-[#f0dfe2] text-[#935b68]' };
  return <div className="rounded-2xl border border-border bg-card p-4 shadow-[var(--shadow-sm)] transition-transform hover:-translate-y-0.5"><div className="flex items-start justify-between"><div className={`grid h-9 w-9 place-items-center rounded-xl ${colors[tint]}`}><Icon className="h-[18px] w-[18px]" /></div><span className="font-mono text-[10px] text-muted-foreground">DEMO</span></div><div className="mt-4 text-2xl font-extrabold tracking-[-.04em] text-[#18343b]">{value}</div><div className="mt-1 text-xs font-semibold text-muted-foreground">{label}</div><div className="mt-2 text-[11px] font-medium text-[#2c8c83]">{detail}</div></div>;
}

